 EXECUTE 'SELECT jsonb_build_object(''signature'',''public.mission_generic_room_state_v1(uuid)'',''oid'',p.oid::bigint,''owner'',pg_get_userbyid(p.proowner),''acl'',p.proacl::text,''config'',to_jsonb(p.proconfig),''secdef'',p.prosecdef,''volatility'',p.provolatile::text,''language'',l.lanname,''source_md5'',md5(p.prosrc),''ddl_md5'',md5(pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(''public.mission_generic_room_state_v1(uuid)'')' INTO heads;
 IF ((heads-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_room_state_v1(uuid)","source_md5":"dc2cf282367e2add9c79cd11fab8b80d","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NATIVE_INTENT_ATTRS' USING ERRCODE='P0001';END IF;
 IF (heads->>'oid'='50484') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NATIVE_INTENT_EXISTING_OID' USING ERRCODE='P0001';END IF;
 newpre:=jsonb_set(newpre,'{db_core,pins}',(SELECT jsonb_agg(CASE WHEN h->>'signature' IN('public.mission_generic_room_state_v1(uuid)','mission_generic_room_state_v1(uuid)') THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>'{db_core,pins}') WITH ORDINALITY rows(h,ord)));
 newpre:=jsonb_set(newpre,'{db_core,target_bodies}',(SELECT jsonb_agg(CASE WHEN h->>'signature' IN('public.mission_generic_room_state_v1(uuid)','mission_generic_room_state_v1(uuid)') THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>'{db_core,target_bodies}') WITH ORDINALITY rows(h,ord)));
 newpre:=jsonb_set(newpre,'{db_core,c1266_functions}',(SELECT jsonb_agg(CASE WHEN h->>'signature' IN('public.mission_generic_room_state_v1(uuid)','mission_generic_room_state_v1(uuid)') THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>'{db_core,c1266_functions}') WITH ORDINALITY rows(h,ord)));
 newpre:=jsonb_set(newpre,'{db_core,all_function_headers}',(SELECT jsonb_agg(CASE WHEN h->>'signature' IN('public.mission_generic_room_state_v1(uuid)','mission_generic_room_state_v1(uuid)') THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>'{db_core,all_function_headers}') WITH ORDINALITY rows(h,ord)));
 newpre:=jsonb_set(newpre,'{db_core,additional_dependencies}',(SELECT jsonb_agg(CASE WHEN h->>'signature' IN('public.mission_generic_room_state_v1(uuid)','mission_generic_room_state_v1(uuid)') THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>'{db_core,additional_dependencies}') WITH ORDINALITY rows(h,ord)));
 newpre:=jsonb_set(newpre,'{db_core,context24_functions}',(SELECT jsonb_agg(CASE WHEN h->>'signature' IN('public.mission_generic_room_state_v1(uuid)','mission_generic_room_state_v1(uuid)') THEN (SELECT jsonb_object_agg(k,CASE WHEN k='signature' THEN v WHEN k='oid' AND jsonb_typeof(v)='string' THEN to_jsonb(heads->>'oid') ELSE coalesce(heads->k,v) END) FROM jsonb_each(h) fields(k,v)) ELSE h END ORDER BY ord) FROM jsonb_array_elements(newpre#>'{db_core,context24_functions}') WITH ORDINALITY rows(h,ord)));
 expected:=jsonb_set(expected,'{headers}',(SELECT jsonb_agg(x ORDER BY x->>'signature') FROM (SELECT CASE WHEN h->>'signature'='public.mission_generic_room_state_v1(uuid)' THEN heads ELSE h END x FROM jsonb_array_elements(expected->'headers') h ) z));
 root_text:=newpre::text;
 IF (octet_length(root_text)<=262144) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NATIVE_INTENT_ROOT_SIZE' USING ERRCODE='P0001';END IF;
 root_sha:=encode(extensions.digest(convert_to(root_text,'UTF8'),'sha256'),'hex');
 UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=root_text,revision_sha256=root_sha,observed_revision_sha256=root_sha,client_build='mission-factory-admin/2:'||root_sha,updated_at=clock_timestamp() WHERE singleton AND revision_sha256='6e2d2c26348585b88dc5c6e95e937c6c9520b21a2cd4000e33e1fe7438b1ad1b';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF (n=1) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NATIVE_INTENT_ROOT_CAS' USING ERRCODE='P0001';END IF;
 UPDATE mission_factory_owner.c464_control SET release_sha256=root_sha WHERE singleton;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF (n=1) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NATIVE_INTENT_G2_CAS' USING ERRCODE='P0001';END IF;
 UPDATE mission_factory_owner.provider_authoring_admissions SET release_sha256=root_sha WHERE actor_user IN('b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b','f0856d53-83a6-4de0-bc0c-12c87916e665');
